package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.BlockPos;
/** Bounded diagnosis of real selected regions, not a blind expanded search. */
public final class ReimaginedSurvey {
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STARTED.register(server->{try{var level=server.overworld();var g=(RealisticGenerator)level.getChunkSource().getGenerator();var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();long id=Thread.currentThread().threadId(),bytes=bean.getThreadAllocatedBytes(id),start=System.nanoTime();var sites=new ReimaginedSites().bind(level.getSeed(),g,level.getChunkSource().randomState());var out=new LinkedHashMap<String,Object>();out.put("bindNanos",System.nanoTime()-start);out.put("bindAllocatedBytes",bean.getThreadAllocatedBytes(id)-bytes);write("bind.json",out);var rows=new ArrayList<Object>();for(int kind=1;kind<=5;kind++){out.put("regions"+kind,sites.regionCount(kind));int attempts=0;for(var r:sites.ordered(kind,BlockPos.ZERO,6000000)){start=System.nanoTime();bytes=bean.getThreadAllocatedBytes(id);var plan=r.plan();var row=new LinkedHashMap<String,Object>();row.put("kind",kind);row.put("owner",r.owner());row.put("nanos",System.nanoTime()-start);row.put("allocatedBytes",bean.getThreadAllocatedBytes(id)-bytes);row.put("accepted",plan.isPresent());plan.ifPresent(p->row.put("plan",p));rows.add(row);write("regions.json",rows);if(plan.isPresent()||++attempts>=12)break;}}out.put("rows",rows);write("survey.json",out);Files.writeString(Path.of("result.txt"),"PASS bounded survey");}catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("REIMAGINED_SURVEY_FAIL",t);try{Files.writeString(Path.of("result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{server.halt(false);}});}
 private static void write(String name,Object value)throws Exception{Files.writeString(Path.of(name),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}
}
